3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Business rule: an owner's {@code checkDigit} is a single Luhn check digit (0-9) computed
7	 * over the digits contained in the owner's {@code customerCode}. Kept as a small,
8	 * self-contained unit so the rule can be applied from the read flow without adding
9	 * complexity to the mapper, controller, or service.
10	 */
11	public final class OwnerCheckDigitPolicy {
12	
13	    private OwnerCheckDigitPolicy() {
14	    }
15	
16	    /**
17	     * Derive the Luhn {@code checkDigit} for the given owner, or {@code null} when the
18	     * customer code it is built from is not yet available.
19	     *
20	     * @param owner the owner whose check digit to derive
21	     * @return the Luhn check digit, or {@code null} if it cannot be derived
22	     */
23	    public static Integer checkDigit(Owner owner) {
24	        String customerCode = owner.getCustomerCode();
25	        return customerCode == null ? null : luhn(customerCode);
26	    }
27	
28	    /** Luhn check digit (0-9) over the digits contained in {@code s}. */
29	    private static int luhn(String s) {
30	        int sum = 0;
31	        boolean dbl = true;
32	        for (int i = s.length() - 1; i >= 0; i--) {
33	            char c = s.charAt(i);
34	            if (c < '0' || c > '9') {
35	                continue;
36	            }
37	            int d = c - '0';
38	            if (dbl) {
39	                d *= 2;
40	                if (d > 9) {
41	                    d -= 9;
42	                }
43	            }
44	            sum += d;
45	            dbl = !dbl;
46	        }
47	        return (10 - (sum % 10)) % 10;
48	    }
49	}
